CREATE DATABASE IF NOT EXISTS secure_api CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE secure_api;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE api_tokens (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, revoked_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX idx_tokens_expiry(expires_at,revoked_at)) ENGINE=InnoDB;
CREATE TABLE startups (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(180) NOT NULL, description TEXT NULL, website VARCHAR(255) NULL, industry VARCHAR(120) NULL, location VARCHAR(180) NULL, contact_email VARCHAR(190) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE mentors (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(180) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, expertise VARCHAR(180) NULL, bio TEXT NULL, company VARCHAR(180) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE programmes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(180) NOT NULL, description TEXT NULL, start_date DATE NULL, end_date DATE NULL, status ENUM('planned','active','completed','cancelled') NOT NULL DEFAULT 'planned', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, action VARCHAR(40) NOT NULL, resource VARCHAR(40) NOT NULL, resource_id BIGINT UNSIGNED NOT NULL, payload JSON NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), INDEX idx_audit_resource(resource,resource_id), INDEX idx_audit_created(created_at)) ENGINE=InnoDB;
CREATE TABLE rate_limits (rate_key VARCHAR(100) PRIMARY KEY, window_start BIGINT NOT NULL, request_count INT UNSIGNED NOT NULL DEFAULT 0, INDEX idx_rate_window(window_start)) ENGINE=InnoDB;
